// Patches the v2 table with the K1 zone-up literals from t8v2. Does not overwrite v2.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const src = JSON.parse(readFileSync(resolve('work/out/accept-table-t8-v2.json'), 'utf8'));
const DIRECT = '9d6a92dc9914061304a8f94e2515a22b5fd6ba2846405649f740cc62282aea02';
const halfUp = JSON.parse(JSON.stringify(src.presets.halfBoot));
halfUp.k5962 = halfUp.k5962.slice();
halfUp.k5962[0] = 409;
halfUp.k88b2 = [409];
src.presets.halfUp = halfUp;
src.table = 'accept-table-t8-v3';
const USE = new Set(['zone-up', 'zone-ok', 'e-enter', 'e-up', 'e-dial', 'e-right', 'e-ok', 'n-up']);
for (const step of src.steps) {
  if (step.id === 'zone-up') step.expect.title = DIRECT;
  if (!USE.has(step.id)) continue;
  const half = step.expect.half;
  if (half && half.preset === 'halfBoot') step.expect.half = { preset: 'halfUp' };
}
const out = resolve('work/out/accept-table-t8-v3.json');
writeFileSync(out, JSON.stringify(src, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, direct: DIRECT, k5962: halfUp.k5962, k88b2: halfUp.k88b2 }) + '\n');
